function numberOfSubsequences(nums) {
  const n = nums.length;
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const ratioKey = (top, bottom) => {
    const divisor = gcd(top, bottom);
    return (top / divisor) * 1001 + bottom / divisor;
  };
  const ratios = new Map();
  let count = 0;
  for (let r = 4; r < n - 2; r++) {
    const q = r - 2;
    for (let p = 0; p <= q - 2; p++) {
      const key = ratioKey(nums[p], nums[q]);
      ratios.set(key, (ratios.get(key) ?? 0) + 1);
    }
    for (let s = r + 2; s < n; s++) {
      count += ratios.get(ratioKey(nums[s], nums[r])) ?? 0;
    }
  }
  return count;
}

