function numberOfSubsequences(nums) {
  // Check every quadruple with gaps of at least two directly.
  const n = nums.length;
  let count = 0;
  for (let p = 0; p < n; p++)
    for (let q = p + 2; q < n; q++)
      for (let r = q + 2; r < n; r++)
        for (let s = r + 2; s < n; s++)
          if (nums[p] * nums[r] === nums[q] * nums[s]) count++;
  return count;
}

