function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const pools = [[1, 2], [1, 2, 3, 4], [2, 3, 4, 6, 8, 12], [1, 2, 4, 8, 16], [5, 10, 15, 30], [7, 11, 13, 77, 91, 143]];
  if (size === 'small') {
    const n = int(7, 16);
    const pool = rand() < 0.8 ? pick(pools) : Array.from({ length: 12 }, () => int(1, 1000));
    return [Array.from({ length: n }, () => pick(pool))];
  }
  const n = int(950, 1000);
  const top = int(500, 1000);
  const value = int(1, 1000);
  const pool = pick(pools);
  // Random values up to top, values from a pool of related numbers, all equal (the largest answers), or divisors of 1000.
  const mode = int(0, 3);
  if (mode === 0) return [Array.from({ length: n }, () => int(1, top))];
  if (mode === 1) return [Array.from({ length: n }, () => pick(pool))];
  if (mode === 2) return [new Array(n).fill(value)];
  return [Array.from({ length: n }, () => pick([1, 2, 4, 5, 8, 10, 20, 25, 40, 50, 100, 125, 200, 250, 500, 1000]))];
}
